'use strict';

// MODULES //

var tape = require( 'tape' );
var Float64Array = require( '@stdlib/array/float64' );
var hasProp = require( '@stdlib/assert/has-property' );
var isFunction = require( '@stdlib/assert/is-function' );
var namedtypedtuple = require( './../lib' );


// TESTS //

tape( 'main export is a function', function test( t ) {
	t.ok( true, __filename );
	t.strictEqual( typeof namedtypedtuple, 'function', 'main export is a function' );
	t.end();
});

tape( 'a tuple has a `set` method', function test( t ) {
	var Point;
	var p;

	Point = namedtypedtuple( [ 'x', 'y' ] );
	p = new Point();

	t.strictEqual( hasProp( p, 'set' ), true, 'returns expected value' );
	t.strictEqual( isFunction( p.set ), true, 'returns expected value' );
	t.end();
});

tape( 'the method throws an error if invoked with a `this` context which is not a tuple instance', function test( t ) {
	var values;
	var Point;
	var p;
	var i;

	Point = namedtypedtuple( [ 'x', 'y' ] );
	p = new Point();

	values = [
		'5',
		5,
		NaN,
		true,
		false,
		null,
		void 0,
		{},
		[],
		function noop() {}
	];
	for ( i = 0; i < values.length; i++ ) {
		t.throws( badValue( values[i] ), TypeError, 'throws an error when provided '+values[i] );
	}
	t.end();

	function badValue( value ) {
		return function badValue() {
			return p.set.call( value, [ 1, 2 ] );
		};
	}
});

tape( 'the method throws an error if the source array plus offset exceeds the tuple length', function test( t ) {
	var values;
	var Point;
	var p;
	var i;

	Point = namedtypedtuple( [ 'x', 'y', 'z' ] );
	p = new Point( [ 1, 2, 3 ] );

	values = [
		[ [ 7, 8 ], 3 ],
		[ [ 1, 2, 3, 4 ], 0 ],
		[ [ 1, 2 ], 2 ]
	];
	for ( i = 0; i < values.length; i++ ) {
		t.throws( badValue( values[ i ] ), RangeError, 'throws an error when provided arguments '+values[ i ] );
	}
	t.end();

	function badValue( args ) {
		return function badValue() {
			p.set( args[ 0 ], args[ 1 ] );
		};
	}
});

tape( 'the method returns `undefined`', function test( t ) {
	var Point;
	var out;
	var p;

	Point = namedtypedtuple( [ 'x', 'y', 'z' ] );
	p = new Point( [ 1, 2, 3 ] );
	out = p.set( [ 7, 8 ] );

	t.strictEqual( out, void 0, 'returns expected value' );
	t.end();
});

tape( 'the method sets tuple elements from an array-like object', function test( t ) {
	var Point;
	var p;

	Point = namedtypedtuple( [ 'x', 'y', 'z' ] );
	p = new Point( [ 1, 2, 3 ] );

	p.set( [ 7, 8 ] );

	t.strictEqual( p[ 0 ], 7, 'returns expected value' );
	t.strictEqual( p[ 1 ], 8, 'returns expected value' );
	t.strictEqual( p[ 2 ], 3, 'returns expected value' );

	// Field values reflect the update:
	t.strictEqual( p.x, 7, 'returns expected value' );
	t.strictEqual( p.y, 8, 'returns expected value' );
	t.strictEqual( p.z, 3, 'returns expected value' );
	t.end();
});

tape( 'the method sets tuple elements from a typed array', function test( t ) {
	var Point;
	var p;

	Point = namedtypedtuple( [ 'x', 'y', 'z' ] );
	p = new Point( [ 1, 2, 3 ] );

	p.set( new Float64Array( [ 7, 8 ] ) );

	t.strictEqual( p[ 0 ], 7, 'returns expected value' );
	t.strictEqual( p[ 1 ], 8, 'returns expected value' );
	t.strictEqual( p[ 2 ], 3, 'returns expected value' );

	// Field values reflect the update:
	t.strictEqual( p.x, 7, 'returns expected value' );
	t.strictEqual( p.y, 8, 'returns expected value' );
	t.strictEqual( p.z, 3, 'returns expected value' );
	t.end();
});

tape( 'the method supports specifying an offset', function test( t ) {
	var Point;
	var p;

	Point = namedtypedtuple( [ 'x', 'y', 'z' ] );
	p = new Point( [ 1, 2, 3 ] );

	p.set( [ 9 ], 2 );

	t.strictEqual( p[ 0 ], 1, 'returns expected value' );
	t.strictEqual( p[ 1 ], 2, 'returns expected value' );
	t.strictEqual( p[ 2 ], 9, 'returns expected value' );

	// Field values reflect the update:
	t.strictEqual( p.x, 1, 'returns expected value' );
	t.strictEqual( p.y, 2, 'returns expected value' );
	t.strictEqual( p.z, 9, 'returns expected value' );
	t.end();
});

tape( 'the method updates values accessible via field names', function test( t ) {
	var Point;
	var p;

	Point = namedtypedtuple( [ 'x', 'y', 'z' ] );
	p = new Point( [ 1, 2, 3 ] );

	p.set( [ 7, 8 ] );

	t.strictEqual( p.x, 7, 'returns expected value' );
	t.strictEqual( p.y, 8, 'returns expected value' );
	t.strictEqual( p.z, 3, 'returns expected value' );
	t.end();
});
